#!/usr/bin/env ruby
# frozen_string_literal: true

require "yaml"

# Code generator for Prism sub-location invariant checks (node_locations.inc).
module PrismHarnessCodegen
  module_function

  def generate_node_locations(config_path, out_path)
    tmp_path = nil
    config = YAML.safe_load_file(config_path)
    lines = [
      "/*----------------------------------------------------------------------------*/",
      "/* This file is generated by harnesses/prism/gen_node_locations.rb from       */",
      "/* config.yml and should not be modified manually.                            */",
      "/*----------------------------------------------------------------------------*/",
      ""
    ]

    config.fetch("nodes").each do |node|
      loc_fields = (node["fields"] || []).select { |f| f["type"] == "location" || f["type"] == "location?" }
      next if loc_fields.empty?

      human = node.fetch("name").gsub(/(?<=.)[A-Z]/, "_\\0").downcase
      lines << "    case PM_#{human.upcase}: {"
      lines << "        const pm_#{human}_t *cast = (const pm_#{human}_t *) node;"
      loc_fields.each do |field|
        fname = field.fetch("name")
        lines << "        fuzz_check_sub_location(node, \"#{fname}\", cast->#{fname}, ctx);"
      end
      lines << "        break;"
      lines << "    }"
    end

    contents = "#{lines.join("\n")}\n"
    abort("Non-ASCII character in generated #{out_path}") unless contents.ascii_only?

    tmp_path = "#{out_path}.tmp.#{Process.pid}"
    File.write(tmp_path, contents)
    File.rename(tmp_path, out_path)
    out_path
  ensure
    File.delete(tmp_path) if tmp_path && File.exist?(tmp_path)
  end

  def run_node_locations_cli(argv = ARGV)
    repo_root = File.expand_path("../..", __dir__)
    default_prism = ENV["PRISM_A_DIR"] || File.join(repo_root, "tmp/fuzz/build/targets/prism_a")
    config_path = argv[0] || File.join(default_prism, "config.yml")
    out_path = argv[1] || File.join(repo_root, "tmp/fuzz/build/targets/gen/prism_a/node_locations.inc")
    generate_node_locations(config_path, out_path)
  end

  alias_method :run_cli, :run_node_locations_cli
  module_function :run_cli
end

if __FILE__ == $PROGRAM_NAME
  # Keep `out_path` bound in CLI scope for appended compatibility probe hooks in test/triage/repro_test.rb.
  out_path = PrismHarnessCodegen.run_cli(ARGV)
  abort("Missing generated #{out_path}") unless File.file?(out_path)
end
